const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

const reminderId = crypto.randomUUID();
const content = 'Aurora Smart Desk Lamp Pro (PROD-73FAB4) — Key Details: Price: \$88.00 | In Stock: Yes (24 units) | Warranty: 12 months | Return Window: 30 days (0% restocking fee) | Shipping: 3 days | Specs: 12W LED, 2700K-6500K adjustable color temp, dimmable, Aluminum + ABS | Brand: Aurora Home';

// Use current-style timestamp consistent with existing entries (Sept 2026 timeframe)
const creationTimestamp = 1788314400; // 2026-09-02T10:00:00 UTC
const reminderTimestamp = 1788314400;
const createdAt = '2026-09-02T10:00:00';

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, ?)
\`).run(reminderId, content, creationTimestamp, reminderTimestamp, createdAt);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('=== Reminder Created ===');
console.log(JSON.stringify(row, null, 2));
"
